other_files.jobs/retry.go:
package jobs

// runSafely recovers a panicking handler and requeues its job.
func runSafely(q chan<- Job, j Job) {
	defer func() {
		if recover() != nil {
			q <- j
		}
	}()
	j.Run()
}

